import numpy as np, pandas as pd, warnings, pickle
from pymatgen.core import Structure, Element
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from pymatgen.analysis.molecule_structure_comparator import CovalentRadius
warnings.filterwarnings('ignore')

def stats(d,prefix,vals,weights=None):
    a=np.array(vals,float); w=np.ones(len(a)) if weights is None else np.array(weights,float)
    ok=np.isfinite(a);a=a[ok];w=w[ok]
    if len(a)==0 or w.sum()==0:
        for k in ['mean','std','min','max','range']:d[prefix+'_'+k]=np.nan
        return
    w=w/w.sum();m=np.sum(a*w)
    for k,v in zip(['mean','std','min','max','range'],[m,np.sqrt(np.sum(w*(a-m)**2)),a.min(),a.max(),a.max()-a.min()]):d[prefix+'_'+k]=v

attrs=['Z','X','atomic_mass','atomic_radius','atomic_radius_calculated','row','group','mendeleev_no','electron_affinity','ionization_energy','molar_volume','melting_point','boiling_point','bulk_modulus','thermal_conductivity','van_der_waals_radius']

def getel(e,a):
    try:return float(getattr(e,a))
    except:return np.nan

def features(s):
    d={}; c=s.composition; els=list(c.elements);am=[c[e] for e in els];w=np.array(am)/sum(am)
    for attr in attrs: stats(d,'el_'+attr,[getel(e,attr) for e in els],w)
    for typ in ['metal','transition_metal','alkali','alkaline','metalloid','halogen','chalcogen','lanthanoid']:
        d['frac_'+typ]=sum(wi*getattr(e,'is_'+typ) for e,wi in zip(els,w))
    for block in ['s','p','d','f']:d['block_'+block]=sum(wi*(e.block==block) for e,wi in zip(els,w))
    for e in Element:
        if e.Z<=94:d['frac_'+e.symbol]=c.get_atomic_fraction(e)
    d['nelements']=len(els);d['entropy']=-np.sum(w*np.log(w))
    for power in [2,3,5,7,10]:d['stoich_'+str(power)]=sum(w**power)**(1/power)
    stats(d,'en_diff',[abs(e.X-f.X) for e in els for f in els],[we*wf for we in w for wf in w])
    stats(d,'ionicity',[1-np.exp(-(e.X-f.X)**2/4) for e in els for f in els],[we*wf for we in w for wf in w])
    # Effective valence orbital population and atomic frontier energy
    for prop in ['sval','pval','dval','fval','homo','lumo','hardness']:
        vals=[]
        for e in els:
            try:
                config=e.full_electronic_structure;outer=max(x[0] for x in config)
                if prop in ['sval','pval','dval','fval']:
                    b=prop[0]; vals.append(sum(z for n,l,z in config if l==b and n==outer-{'s':0,'p':0,'d':1,'f':2}[b]))
                elif prop=='homo':vals.append(max(e.atomic_orbitals.values()))
                elif prop=='lumo':vals.append(-e.electron_affinity)
                else:vals.append(e.ionization_energy-e.electron_affinity)
            except:vals.append(np.nan)
        stats(d,prop,vals,w)
    d['nsites']=len(s);d['vpa']=s.volume/len(s);d['density']=float(s.density)
    d['packing']=sum(4*np.pi*CovalentRadius.radius[e.symbol]**3/3 for e in s.species)/s.volume
    a=SpacegroupAnalyzer(s,symprec=0.05)
    d['sg']=a.get_space_group_number();pg=a.get_point_group_symbol()
    d['polar']=int(pg in ['1','2','m','mm2','3','3m','4','4mm','6','6mm'])
    d['nsymm']=len(a.get_symmetry_operations());d['nunique']=len(set(a.get_symmetry_dataset().equivalent_atoms))
    for name in ['triclinic','monoclinic','orthorhombic','tetragonal','trigonal','hexagonal','cubic']:d['sys_'+name]=int(a.get_crystal_system()==name)
    std=a.get_conventional_standard_structure()
    abc=sorted(std.lattice.abc);d['cell_aniso']=abc[-1]/abc[0]
    d['len_mid_min']=abc[1]/abc[0]
    # Local environments
    i,j,img,dist=s.get_neighbor_list(5)
    radii=np.array([CovalentRadius.radius[e.symbol] for e in s.species]);en=np.array([e.X for e in s.species])
    norm=dist/(radii[i]+radii[j]);disp=s.cart_coords[j]+img@s.lattice.matrix-s.cart_coords[i]
    for threshold in [1.1,1.25,1.5]:
        take=norm<threshold;ii=i[take];jj=j[take];dd=dist[take];nn=norm[take];dv=disp[take]
        pr='bond'+str(threshold)
        stats(d,pr+'_dist',dd);stats(d,pr+'_normdist',nn);stats(d,pr+'_endiff',abs(en[ii]-en[jj]));stats(d,pr+'_bond_strength',1/dd**3)
        cn=np.bincount(ii,minlength=len(s));stats(d,pr+'_cn',cn)
        local=[];charges=[]
        for ix in range(len(s)):
            ixm=ii==ix;unit=dv[ixm]/dd[ixm,None]
            local.append(np.linalg.norm(np.sum(unit,axis=0))/max(1,len(unit)))
            charges.append(sum(en[jj[ixm]]-en[ix]))
        stats(d,pr+'_asymm',local);stats(d,pr+'_charge',charges)
        for group,site_mask in [('metal',np.array([e.is_metal for e in s.species])),('nonmetal',np.array([not e.is_metal for e in s.species]))]:
            stats(d,pr+'_cn_'+group,cn[site_mask]);stats(d,pr+'_asymm_'+group,np.array(local)[site_mask])
        d[pr+'_under2']=np.mean(cn<2);d[pr+'_under3']=np.mean(cn<3)
    # Nearest neighborhood independent of radii
    min_d=[];local_cn=[];local_as=[]
    for ix in range(len(s)):
        ds=dist[i==ix];dvs=disp[i==ix];order=np.argsort(ds);ds=ds[order];dvs=dvs[order]
        min_d.append(ds[0]);take=ds<ds[0]*1.2;local_cn.append(take.sum());local_as.append(np.linalg.norm(np.sum(dvs[take]/ds[take,None],axis=0))/take.sum())
    stats(d,'nearest_dist',min_d);stats(d,'nearest_cn',local_cn);stats(d,'nearest_asymm',local_as)
    return d

if __name__=='__main__':
    tr=pd.read_csv('/work/cdft_piezo_d_eg_train.csv');p=pd.read_csv('/work/cdft_piezo_pool.csv');df=pd.concat([tr,p],ignore_index=True)
    fs=[]
    for k,r in df.iterrows():
        fs.append(features(Structure.from_str(r.poscar,fmt='poscar')))
        if k%50==0:print(k,flush=True)
    X=pd.DataFrame(fs);X.to_pickle('/tmp/features.pkl');print(X.shape)

