import pandas as pd,numpy as np,warnings
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from sklearn.model_selection import GroupKFold
from sklearn.metrics import mean_absolute_error
from catboost import CatBoostRegressor
warnings.filterwarnings('ignore')
tr=pd.read_csv('/work/cdft_piezo_d_eg_train.csv');p=pd.read_csv('/work/cdft_piezo_pool.csv');X=pd.read_pickle('/tmp/features.pkl').fillna(0)
xs=pd.read_pickle('/tmp/springs.pkl');X=pd.concat([X,np.log1p(xs.clip(0)*1000)],axis=1)
X=X.loc[:,X.iloc[:200].std()>1e-6];xt=X.iloc[:200];xp=X.iloc[200:]
res=p.drop(columns='poscar').copy();high=tr.band_gap>=5
for typ in ['log','raw','eligible']:
 ix=tr.index if typ!='eligible' else tr[tr.band_gap>4].index
 y=tr.d_ij.clip(upper=80).values
 if typ=='log':y=np.log1p(tr.d_ij)
 for name in ['cb','et']:
  if name=='cb':m=CatBoostRegressor(iterations=1200,depth=4,learning_rate=.025,l2_leaf_reg=6,verbose=False,thread_count=4,random_seed=22)
  else:m=ExtraTreesRegressor(n_estimators=600,max_features=.7,min_samples_leaf=2,n_jobs=4,random_state=22)
  oof=np.zeros(len(ix))
  for it,iv in GroupKFold(5).split(xt.iloc[ix],y[ix],tr.formula[ix]):
   m.fit(xt.iloc[ix[it]],y[ix[it]]);oof[iv]=m.predict(xt.iloc[ix[iv]])
  if typ=='log':oof=np.expm1(oof)
  print(typ,name,'MAE',mean_absolute_error(tr.d_ij[ix],oof),'HIGH MAE',mean_absolute_error(tr.d_ij[ix][high[ix]],oof[high[ix]]),flush=True)
  m.fit(xt.iloc[ix],y[ix]);pred=m.predict(xp)
  if typ=='log':pred=np.expm1(pred)
  res[typ+'_'+name]=pred
  if name=='cb':print(pd.Series(m.feature_importances_,index=X.columns).nlargest(12).to_string())
res.to_pickle('/tmp/refine.pkl');pr=pd.read_pickle('/tmp/pred.pkl');res['band_gap']=pr.band_gap
print(res[res.band_gap>=4.4].sort_values('raw_cb',ascending=False).round(2).to_string(index=False))

